mapper.select:
SELECT ID, PERSON_ID, TAG_ID, SOURCE_TYPE AS SOURCE, SOURCE_REF, STATUS, RULE_ID, BATCH_NO,
       MATCHED_KEYWORD, REVIEWED_BY, REVIEWED_AT, CREATED_AT, UPDATED_AT
FROM (
    SELECT PT.*, ROW_NUMBER() OVER (
        ORDER BY CASE STATUS WHEN 'APPROVED' THEN 1 WHEN 'PENDING' THEN 2 ELSE 3 END,
                 CASE SOURCE_TYPE WHEN 'MANUAL' THEN 1 WHEN 'REMOTE' THEN 2 ELSE 3 END,
                 CREATED_AT
    ) AS RN
    FROM PT_PERSON_TAG PT WHERE PERSON_ID = #{personId} AND TAG_ID = #{tagId}
) PREFERRED WHERE RN = 1

SELECT ID, PERSON_ID, TAG_ID, SOURCE_TYPE AS SOURCE, SOURCE_REF, STATUS, RULE_ID, BATCH_NO,
       MATCHED_KEYWORD, REVIEWED_BY, REVIEWED_AT, CREATED_AT, UPDATED_AT
FROM PT_PERSON_TAG WHERE ID = #{id}

mapper.update:
UPDATE PT_PERSON_TAG SET SOURCE_TYPE = #{source}, SOURCE_REF = #{sourceRef}, STATUS = #{status}, RULE_ID = #{ruleId},
    BATCH_NO = #{batchNo}, MATCHED_KEYWORD = #{matchedKeyword}, REVIEWED_BY = #{reviewedBy},
    REVIEWED_AT = #{reviewedAt}, UPDATED_AT = #{updatedAt}
WHERE ID = #{id}

UPDATE PT_PERSON_TAG SET STATUS = #{status}, REVIEWED_BY = #{reviewer},
    REVIEWED_AT = #{reviewedAt}, UPDATED_AT = #{reviewedAt}
WHERE ID = #{id}

mapper.delete:
DELETE FROM PT_PERSON_TAG WHERE PERSON_ID = #{personId} AND SOURCE_TYPE = 'RULE' AND STATUS != 'REJECTED' AND RULE_ID IN (SELECT ID FROM PT_TAG_RULE)
AND RULE_ID NOT IN
#{ruleId}

mapper.update:
UPDATE PT_PERSON_TAG SET STATUS = 'EXPIRED', UPDATED_AT = #{updatedAt}
WHERE PERSON_ID = #{personId} AND TAG_ID = #{tagId} AND SOURCE_TYPE = 'RULE'
  AND SOURCE_REF = #{sourceRef}
